  let html='<div class="b-assumptions-box b-explain" data-explain="'+esc(tool)+'" data-teaser="'+esc(teaser.slice(0,160))+'"><p class="calc-kicker">COSA CONTA IN QUESTO CALCOLO</p>';
  html+='<p class="b-explain-aim"><b>Cosa cerchiamo:</b> '+esc(e.aim||'')+(e.horizon?' <span class="b-explain-horizon">Orizzonte: '+esc(e.horizon)+'</span>':'')+'</p>';
