 const SIMS=[['carburant','Carburante (veicoli)',[['distance','Distanza per partita (km)'],['consommation','Consumo (litri per 100 km)'],['prixUnitaire','Prezzo al litro ($)']]],['entretien','Manutenzione (veicoli)',[['parPartie','Costo per partita ($)']]],['reparation','Riparazioni (veicoli)',[['parPartie','Costo per partita ($)']]],['assurance','Assicurazione (veicoli)',[['parPartie','Costo per partita ($)']]],['munitions','Munizioni (ogni tentativo di missione)',[['parTentative','Costo per tentativo ($)']]],['echec','Tentativi falliti (Le mie attività, Il mio obiettivo, Il mio tempo di gioco)',[['tentativesRatees','Tentativi falliti su 10']]]];
